import os
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        query_text TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department - internal API for HR dashboard"""
    department = request.args.get('department', '')
    include_inactive = request.args.get('include_inactive', 'false')

    # Validate department is not empty
    if not department:
        return jsonify({'error': 'department parameter required'}), 400

    # Log the search for compliance
    db = get_db()
    log_query = f"Search: department={department}"
    db.execute("INSERT INTO audit_log (action, query_text) VALUES ('search', ?)", (log_query,))

    # Build query based on parameters
    if include_inactive == 'true':
        query = f"SELECT id, username, role, department FROM users WHERE department = '{department}'"
    else:
        query = f"SELECT id, username, role, department FROM users WHERE department = '{department}' AND role != 'inactive'"

    try:
        results = db.execute(query).fetchall()
        users = [dict(row) for row in results]
        return jsonify({'users': users, 'count': len(users)})
    except sqlite3.Error as e:
        return jsonify({'error': 'Database error', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID - uses parameterized query"""
    db = get_db()
    result = db.execute("SELECT id, username, role, department FROM users WHERE id = ?", (user_id,)).fetchone()
    if result:
        return jsonify(dict(result))
    return jsonify({'error': 'not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create new user - admin only"""
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'missing fields'}), 400

    password_hash = hashlib.sha256(data['password'].encode()).hexdigest()
    department = data.get('department', 'general')

    db = get_db()
    try:
        db.execute(
            "INSERT INTO users (username, password_hash, department) VALUES (?, ?, ?)",
            (data['username'], password_hash, department)
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'username exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
